console.log(new Intl.NumberFormat('en-US').format(n));
console.log(new Intl.NumberFormat('de-DE').format(n));
console.log(new Intl.NumberFormat('en-US', { style: 'currency', currency: 'EUR' }).format(19.99));
console.log(new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(19.99));
console.log(new Intl.NumberFormat('en', { notation: 'compact' }).format(1_250_000));   // 1.3M
console.log(new Intl.NumberFormat('en', { style: 'percent' }).format(0.075));          // 7.5%
console.log(new Intl.NumberFormat('en', { style: 'unit', unit: 'kilometer-per-hour' }).format(90));
