import { promisify } from 'node:util';
const run = promisify(execFile);

const { stdout } = await run('echo', ['hello', ';rm -rf /']);
console.log(stdout.trim());     // the semicolon is just text

// WRONG: exec(`echo ${userInput}`) — the shell interprets the input
```

Exit codes, missing binaries and bounded waiting are three separate concerns:

```js
import { spawn } from 'node:child_process';

function runNode(script, args = [], timeoutMs = 10_000) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [script, ...args], { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    child.stdout.on('data', (c) => { out += c; if (out.length > 1e6) child.kill(); });
    child.stderr.on('data', (c) => { err += c; });
    child.on('error', reject);                       // not found, not executable
    const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
    child.on('close', (code, signal) => {
      clearTimeout(timer);
      code === 0 ? resolve(out) : reject(new Error(`exit ${code ?? signal}: ${err.slice(0, 200)}`));
    });
  });
}
console.log(await runNode('-e', ['console.log(1 + 1)']));
```

Graceful shutdown drains what is in flight, then forces the issue:

```js
let stopping = false;
const close = async (signal) => {
  if (stopping) { console.log('second signal, exiting now'); process.exit(1); }
  stopping = true;
  console.log('draining on', signal);
  server.closeAllConnections?.();
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(1), 5000).unref();
};
for (const sig of ['SIGINT', 'SIGTERM']) process.on(sig, () => void close(sig));
```

### Signals and graceful shutdown

A Node process receives SIGINT when the terminal sends an interrupt and SIGTERM when a supervisor asks it to stop. Listen with process.on('SIGINT', handler). Installing a handler suppresses the default behaviour of terminating immediately, which is exactly the point: the handler can close servers, flush logs and finish in-flight work. SIGKILL cannot be caught and SIGSTOP cannot be caught, so they are the escalation path when a graceful stop does not complete.

A correct shutdown orchestrator has a single entry point and runs at most once. The first signal starts the sequence and flips a flag; any later signal is either ignored or, on the second one, escalated to an immediate exit. The sequence is: stop accepting new connections, wait for in-flight requests up to a deadline, close the database and other handles, flush logs, then exit with the appropriate code. Without the flag, a rapid double signal can start two overlapping shutdowns and produce confusing errors from a half-closed server.

Closing a server is not instantaneous. server.close stops listening and calls back once all existing connections have ended; with keep-alive connections that may be a long time, because an idle client holds the socket open. Node provides closeIdleConnections and closeAllConnections on the HTTP server to force the issue. The pragmatic pattern is to call close, wait a bounded interval, then call closeAllConnections and exit. Waiting forever is how a deploy hangs until the orchestrator escalates to SIGKILL and the process is killed mid-write.

Exit codes matter to whatever supervises you. Zero means success, a non-zero code means failure, and 128 plus the signal number reports death by signal in shell convention. process.exitCode is preferable to process.exit because it lets the event loop drain naturally; calling process.exit forcibly terminates pending asynchronous writes, which can truncate a log line or lose a database commit. Set the code, then let the loop empty. Reserve process.exit for the case where something is genuinely wedged and you have already tried to close cleanly.

The event loop and the process lifetime are linked. A Node process stays alive while there are pending timers, open sockets, active handles or refs. server.unref and timer.unref remove an object from the count so it no longer keeps the process alive, which is how you create a background timer that does not prevent exit. Conversely a forgotten setInterval keeps a process running forever and is one of the most common causes of a container that will not stop. Listing the handles with process._getActiveHandles in debugging shows what is holding a process open.

Uncaught errors are a last resort, not a control flow. An uncaught exception leaves the process in an undefined state, so the correct response is to log it in full, attempt a bounded cleanup and exit non-zero so the supervisor restarts you. An unhandled promise rejection terminates the process in current versions; treating that as a crash rather than ignoring it is the whole reason for the change. In both cases, install the handler at the very top of the entry point, before any other import can throw, so the handler exists for module-load failures too.

### Environment, stdio and process metadata

process.env is a plain object whose values are always strings or undefined. getenv with a default is a one-liner you should write once: const value = process.env.PORT ?? '3000'. Because the object is string-valued, a common bug is comparing process.env.DEBUG to a boolean or expecting process.env.TIMEOUT to be a number. Convert at the boundary and validate the result; a missing or malformed variable should be reported at startup with a clear message rather than producing NaN halfway through a request. Reading env once at startup into a typed configuration object makes the rest of the program free of string lookups.

stdio is configured per file descriptor as an array or a string shorthand. 'pipe' creates a stream, 'inherit' shares the parent's descriptor, 'ignore' discards it and a number shares an existing descriptor. Passing 'inherit' for all three is the same as stdio: 'inherit'. When you pass 'pipe' and then never attach a data handler, the child's write blocks once the pipe buffer fills, and the child hangs. That single mistake explains most cases of a child process mysteriously stalling forever while doing nothing observable.

Standard output is a stream with its own buffering, and it differs from standard error. When stdout is a terminal it is generally synchronous on POSIX, and when it is a pipe it is asynchronous. Writing a large amount of output and then exiting immediately can truncate the tail, because the process ends before the pipe drains. The reliable pattern for CLI tools is to await the drain of process.stdout.write, or to use process.exitCode and let the loop empty rather than calling process.exit. Standard error is unbuffered and is the right place for anything urgent.

Process metadata helps diagnostics and should be logged once at startup. process.pid identifies the process, process.ppid its parent, process.argv the arguments with the interpreter paths in the first two entries, process.execPath the interpreter's own path, process.platform and process.arch the target triple, and process.version the runtime version. process.argv0 is the original executable name. Logging the platform, architecture, runtime version and process id at boot turns a vague bug report into a reproducible one, and it costs a single line.

A worker runs in its own isolate, so results cross the boundary as cloned messages:

```js
// worker.js
import { parentPort, workerData } from 'node:worker_threads';
const { numbers } = workerData;
const sum = numbers.reduce((a, b) => a + b, 0);
parentPort.postMessage({ sum, received: numbers.length });

// main.js
import { Worker } from 'node:worker_threads';
const run = (file, data) => new Promise((resolve, reject) => {
  const w = new Worker(new URL(file, import.meta.url), { workerData: data });
  w.once('message', resolve);
  w.once('error', reject);
  w.once('exit', (code) => { if (code !== 0) reject(new Error(`worker exit ${code}`)); });
});
console.log(await run('./worker.js', { numbers: [1, 2, 3, 4] }));
```

A pool reuses workers instead of paying startup per task, and restarts a worker that dies:

```js
class Pool {
  #workers = [];
  #queue = [];
  #busy = new Set();
  constructor(size, file) { this.size = size; this.file = file; }

  spawn() {
    const w = new Worker(new URL(this.file, import.meta.url));
    w.on('message', (msg) => {
      this.#busy.delete(w);
      this.#queue.shift()?.resolve(msg);
      this.dispatch();
    });
    w.on('error', (err) => {
      this.#busy.delete(w);
      this.#queue.shift()?.reject(err);
    });
    return w;
  }

  submit(data) {
    return new Promise((resolve, reject) => {
      this.#queue.push({ data, resolve, reject });
      this.dispatch();
    });
  }

  dispatch() {
    while (this.#busy.size < this.size && this.#queue.length) {
      const w = this.spawn();
      this.#busy.add(w);
      w.postMessage(this.#queue[0].data);
    }
  }
}
```

Transferring an ArrayBuffer moves ownership instead of copying it, and the sender is left with a detached buffer:

```js
const buffer = new ArrayBuffer(1024);
const view = new Uint8Array(buffer);
view[0] = 42;
worker.postMessage({ buffer }, [buffer]);
console.log(view.byteLength);     // 0 — detached
```

### Clustering and scaling across cores

The cluster module forks several processes that share one listening port. The primary process binds the socket and distributes incoming connections to the workers, so each worker handles a slice of the traffic with its own event loop and its own memory. On a machine with eight cores, running one process leaves seven idle; cluster or the equivalent built into a process manager is how you use them. Worker processes do not share memory, so any state such as a session cache or a rate-limit counter must move to a shared store.

The default distribution strategy differs by platform. On all platforms except Windows it is round-robin at the primary, which gives an even spread but can lead to a worker that is processing a slow request accepting new ones only in strict turn. The alternative is to let the operating system distribute the accepted connections, which smooths uneven request costs but can be unbalanced when connections are long-lived. Neither is universally better, and the choice matters more for keep-alive connections, where each connection sticks to one worker for its whole life.

Any in-memory state that assumed a single process must be revisited the moment you cluster. Idempotency keys, session data, rate-limit buckets, in-flight job registries, WebSocket connection lists and metrics counters are all per-worker unless externalised. This is the same set of concerns that appears when you add a second server, so treating them as shared from the beginning is the cheaper path. A worker count greater than the core count also hurts, because you are adding context switching and memory pressure without adding compute.

Graceful lifecycle in a cluster means the primary notifies the workers and they shut down in sequence, then the primary exits. If the primary dies without notice, the workers keep running as orphans; if a worker dies unexpectedly, the primary's 'exit' handler should decide whether to respawn. Assigning running tasks to worker ids, load balancing across heterogeneous machines or routes, and rolling restarts all become the primary's job. Beyond a handful of processes, a platform-level orchestrator is the better tool, and the in-process cluster module is really for making a single container use all of its cores.

Health and readiness are not the same check. A worker can be listening and still be unhealthy because its dependencies are down, or unhealthy because it holds stale configuration. A readiness endpoint that verifies the downstream dependencies and the loaded configuration lets the orchestrator remove an instance before it serves errors. Liveness should be a much shallower check, because a liveness probe that fails on a transient dependency outage will restart a perfectly good process and turn a degradation into an outage.

Memory is not shared, so the process count multiplies every per-process baseline. A 200 MB baseline across eight workers is 1.6 GB before any request is served. Workers also each load the runtime, the module graph and the JIT-compiled code. The practical implication is that clustering trades memory for throughput, and on a memory-constrained host it can be strictly worse than a single process. Measure the throughput and the resident set before and after, and be ready to run fewer workers with an explicit concurrency limit rather than assuming the core count is the right number.

A Transform must not buffer the whole input, and its callback decides when the chunk is available:

```js
import { Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';

const upper = new Transform({
  transform(chunk, encoding, done) {
    done(null, String(chunk).toUpperCase());
  },
});

await pipeline(Readable.from(['a\n', 'b\n']), upper, process.stdout);
```

A framer is the one case that genuinely needs a custom transform, because a message can split across chunks:

```js
class LineSplitter extends Transform {
  #tail = '';
  constructor(opts) { super({ ...opts, decodeStrings: false }); }
  _transform(chunk, _enc, done) {
    const parts = (this.#tail + chunk).split('\n');
    this.#tail = parts.pop() ?? '';
    for (const line of parts) if (line) this.push(line);
    done();
  }
  _flush(done) {
    if (this.#tail) this.push(this.#tail);
    done();
  }
}

const split = new LineSplitter();
const lines = [];
split.on('data', (l) => lines.push(l));
for (const piece of ['a\nb', '\nc\n', 'd']) split.write(piece);
split.end();
await new Promise((r) => split.on('end', r));
console.log(lines);       // [ 'a', 'b', 'c', 'd' ]
```

Backpressure is visible as a `false` return from `write`, and the correct response is to wait for `drain`:

```js
async function writeAll(stream, chunks) {
  for (const chunk of chunks) {
    if (!stream.write(chunk)) {
      await new Promise((r) => stream.once('drain', r));
    }
  }
  stream.end();
}

// or just let the pipeline do it
await pipeline(Readable.from(chunks), destination);
```

Async iteration and object mode are the two modern interfaces: `for await (const chunk of readable)` respects backpressure, and in object mode the high water mark counts objects rather than bytes.

### Async iteration and custom streams

Every Readable is async iterable, so for await (const chunk of readable) is the cleanest way to consume one. It respects backpressure, it stops when the stream ends, and an error inside the loop propagates as a rejection. It does not automatically destroy the stream when you break out early, so when you stop before the end, call readable.destroy() in a finally block to release the underlying handle. The promise form of pipeline accepts an async iterable as a source, which makes the whole chain consistent.

Writable streams consume async iterables too via pipeline, and when you build a Transform you generally implement transform(chunk, encoding, callback) and push the result. The callback must be called exactly once, and calling it before push means the output has not been recorded yet, so the reader may see an empty result. In object mode, transform may push nothing to filter a record out, and may push several values to expand one input into many. Do not buffer the whole input to produce one output; that defeats the purpose of the stream and reintroduces the memory problem.

The modern constructor form is stream.Readable.from, Writable and Transform with objectMode options, rather than the function constructors of the early days. Readable.from accepts an iterable or async iterable and handles backpressure from a generator, which makes generators an excellent way to express a data source: a generator that yields chunks and pauses is pulled by the consumer, so a slow consumer slows the producer with no explicit queue. That pull model is the reason generators compose so well into pipelines.

Error handling must be explicit at every stage. A stream emits 'error' once and is then no longer usable; a second error is ignored. The pipeline form handles this, but a hand-written chain must attach an error listener to every stream, destroy the others, and avoid leaking the success callback. If a Writable errors after the reader has begun, the reader should see that error too, which is another thing pipeline does and pipe does not. An unhandled 'error' event on any stream is an uncaught exception and takes the process down.

Choosing to implement a custom stream is often unnecessary. Most transformations are better expressed as generator functions composed into Readable.from or as a Transform whose transform method is a few lines. Custom classes earn their place when you need control over the flush, the object mode boundary or the high water mark, or when you are wrapping a protocol such as a framer that must reassemble messages from arbitrary chunk boundaries. A line splitter is the canonical example: it must buffer a partial line until a newline arrives, and it must emit the trailing partial line on flush.

Finally, remember that not every file needs streaming. Reading a small configuration file or a single JSON document is simpler with readFile and JSON.parse, and the streaming version is roughly the same memory if the file is small but adds failure modes. The decision rule is the size relative to available memory and the latency you can tolerate. Streaming is for data that is large, unbounded, or arriving over time — logs, exports, uploads, network responses — and for everything else the direct read is clearer.

A server that bounds the body, sets content-length and maps errors in one place:

```js
import { createServer } from 'node:http';

const MAX = 64 * 1024;

async function readJson(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX) { const e = new Error('payload too large'); e.status = 413; throw e; }
    chunks.push(chunk);
  }
  if (!chunks.length) return {};
  try { return JSON.parse(Buffer.concat(chunks).toString('utf8')); }
  catch { const e = new Error('invalid JSON'); e.status = 400; throw e; }
}

const server = createServer(async (req, res) => {
  const send = (status, payload) => {
    const body = JSON.stringify(payload);
    res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(body) });
    res.end(body);
  };
  try {
    const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
    if (req.method === 'GET' && url.pathname === '/health') return send(200, { ok: true });
    if (req.method === 'POST' && url.pathname === '/echo') return send(200, { body: await readJson(req) });
    send(404, { error: 'not found' });
  } catch (err) {
    send(err.status ?? 500, { error: err.message });
  }
});
server.headersTimeout = 10_000;
server.requestTimeout = 30_000;
server.listen(0, '0.0.0.0');
```

A client wrapper that checks the status, parses safely and bounds the wait:

```js
async function api(path, { method = 'GET', body, timeout = 8000, retries = 2 } = {}) {
  for (let attempt = 0; ; attempt++) {
    const res = await fetch(`https://example.test${path}`, {
      method,
      headers: body ? { 'content-type': 'application/json' } : {},
      body: body ? JSON.stringify(body) : undefined,
      signal: AbortSignal.timeout(timeout),
    });
    if (res.ok) return res.json();
    if (attempt >= retries || res.status < 500) {
      throw new Error(`${res.status} ${res.statusText}`);
    }
    await new Promise((r) => setTimeout(r, 200 * 2 ** attempt));
  }
}
```

Streaming a large response keeps memory flat, and newline-delimited JSON lets you process it line by line:

```js
const res = await fetch('https://example.test/export.ndjson');
const reader = res.body.pipeThrough(new TextDecoderStream()).getReader();
let buffer = '';
while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  buffer += value;
  const lines = buffer.split('\n');
  buffer = lines.pop() ?? '';
  for (const line of lines) if (line) handle(JSON.parse(line));
}
```

### Clients, timeouts and retries

fetch is available in Node and follows the same rules as the browser version, with a few differences worth knowing. It rejects only on network failure, never on an HTTP error status, so res.ok must be checked explicitly. The response body is a stream that can only be read once; response.json() and response.text() both consume it, so clone the response before reading it twice. redirect is followed by default with 'follow', and setting it to 'manual' exposes the redirect response itself. The body can be a string, a Buffer, a stream or FormData, and setting the content-type header is your job for the first three.

Timeouts need to be explicit. There is no default timeout for fetch in Node, so a request to an unresponsive host can hang until the operating system's TCP timeout, which is measured in minutes. Pass an AbortSignal with AbortSignal.timeout(milliseconds) to bound the whole operation including the body read. For finer control, combine a connect timeout with a total timeout using AbortSignal.any, and remember that aborting after the response headers have arrived still aborts the body read. A request that is not bounded is a request that can consume a connection and a slot in your concurrency limit forever.

Retries are only safe for idempotent operations, and only for the failure classes that are actually transient. Retrying a connection refusal and a 503 with a delay is reasonable; retrying a 400, a 401 or a 422 is not, because the same request will fail identically. An explicit allow-list of retryable statuses and errors is safer than retrying everything that throws. Retrying a non-idempotent POST requires an idempotency key that the server understands, otherwise you will create duplicate resources, charge a card twice or send a message twice; there is no client-side fix for that.

Backoff should be exponential with jitter, and it must respect a maximum attempt count and a total deadline. Jitter — randomising the delay within a window — is what prevents a fleet of clients that failed together from retrying together and hammering the recovering service in synchronised waves. Honour the Retry-After header when it is present, because the server knows when it will be ready. Cap the delay so a user does not wait minutes for a page, and surface the failure rather than retrying silently beyond the point where a human is waiting.

Connection reuse is the throughput lever. A fresh TLS handshake per request costs multiple round trips, so keep an agent or an undici dispatcher with keep-alive enabled and a bounded pool size. In Node, undici is the HTTP client underneath fetch and exposes connection pooling, pipelining and per-origin limits through a dispatcher you can pass as the dispatcher option. Setting a sensible pool size and a keep-alive timeout aligned with the server's own timeout avoids a subtle failure where the client reuses a connection the server has just closed, producing an occasional spurious connection-reset error.

Reading a streaming response is where memory discipline matters again. A large JSON export can be tens of megabytes; consuming it with response.json() materialises the whole object, while iterating response.body as a byte stream lets you parse incrementally. For newline-delimited JSON, accumulate a buffer, split on newlines, parse complete lines and carry the remainder forward — the same boundary problem as any framing. When the consumer is slower than the producer, that natural backpressure from the reader propagates to the socket and keeps memory bounded without any explicit queue.

Structured logs with redaction, and a request id carried through async work:

```js
import { AsyncLocalStorage } from 'node:async_hooks';
import { randomUUID } from 'node:crypto';

const context = new AsyncLocalStorage();
const SECRET = /token|password|authorization|cookie/i;

function redact(value) {
  if (Array.isArray(value)) return value.map(redact);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, SECRET.test(k) ? '[redacted]' : redact(v)]));
  }
  return value;
}

function log(level, msg, fields = {}) {
  const line = { level, time: new Date().toISOString(), msg, requestId: context.getStore()?.id, ...redact(fields) };
  process.stdout.write(`${JSON.stringify(line)}\n`);
}

await context.run({ id: randomUUID() }, async () => {
  log('info', 'request start', { route: '/api/items', password: 'hunter2' });
});
```

The event loop is the resource to watch, and the histogram is how you see it:

```js
import { monitorEventLoopDelay, performance } from 'node:perf_hooks';
const h = monitorEventLoopDelay({ resolution: 20 });
h.enable();

setInterval(() => {
  const p99 = h.percentile(99) / 1e6;
  if (p99 > 50) log('warn', 'event loop delay high', { p99Ms: Math.round(p99) });
}, 5000).unref();

const t = performance.now();
// ... work
log('debug', 'phase done', { ms: Math.round(performance.now() - t) });
```

Memory measured, not guessed, and a profile captured rather than imagined:

```js
const mb = (n) => `${(n / 1024 / 1024).toFixed(1)}MB`;
const m = process.memoryUsage();
console.log('rss', mb(m.rss), 'heap', mb(m.heapUsed), 'external', mb(m.external));

// capture a CPU profile on exit:
//   node --cpu-prof --cpu-prof-dir=profiles app.js
// and a heap snapshot when a threshold is crossed:
```

Liveness stays shallow and readiness carries the dependency checks, because a liveness probe that fails on a transient database blip restarts a healthy fleet:

```js
if (url.pathname === '/live') send(200, { ok: true });
if (url.pathname === '/ready') {
  const dbOk = await ping().then(() => true, () => false);
  send(dbOk ? 200 : 503, { db: dbOk, version: process.env.GIT_SHA ?? 'dev' });
}
```

### Profiling CPU and memory

Measure before optimising, and measure the thing that matters. For CPU, the inspector protocol exposes a profiler that records a sampling profile and aggregates it into a call tree with self and total time per frame. Node's --cpu-prof flag writes a profile on exit that the Chrome DevTools Performance panel can open. For the browser, the Performance panel records a trace with main-thread work, layout and paint. The first step in every case is the same: reproduce the slow path, capture a profile of it, and find the frame that owns the most time rather than the one that appears most often in the source.

Blocking the event loop is the most common performance defect in Node and the easiest to detect. The monitorEventLoopDelay histogram reports the delay between the loop's scheduled and actual wakeups, so a p99 delay of hundreds of milliseconds means something synchronous is hogging the thread. A synchronous JSON.parse of a huge payload, a regular expression with catastrophic backtracking, a synchronous file read and a big sort are the usual culprits. Instrument with per-phase timing, log anything above a threshold, and move genuinely CPU-bound work to a worker thread.

Memory leaks show up as a heap that grows across garbage collections and never returns to a baseline. Take a heap snapshot, exercise the suspected path, force a collection, take a second snapshot and compare the object counts by constructor. Common causes are a cache with no eviction, a listener added per request and never removed, a closure holding a large buffer alive through a small retained reference, and global arrays that accumulate history. Closures and listeners are the two that a leak detector identifies fastest because the retainer path points directly at the owning scope.

The distinction between a leak and a high-water allocation matters. An application that allocates a large buffer per request and releases it will show a sawtooth heap and a high resident set even though nothing leaks. A leak shows a monotonic floor that rises. Measuring the resident set alone conflates the two, so compare the heap used at the bottom of each sawtooth after an explicit collection. If the floor is flat, you have throughput pressure, not a leak, and the fix is pooling rather than hunting for a reference.

Flame graphs answer where the time goes for CPU-bound code and profiles answer where the allocations happen for memory-bound code. The two are complementary, and reading them is a skill: a wide frame high in the tree means many calls; a wide frame deep in the tree means an expensive leaf. Look for a leaf that dominates self time, then decide whether the fix is an algorithm change, fewer allocations or moving the work off the main thread. Micro-optimising a hot leaf that is called rarely, and therefore contributes nothing to total time, is the standard way to spend effort for no gain.

Load testing closes the loop but must be done carefully. Generating artificial load against a shared environment is disruptive, so test locally or in a dedicated environment, and ramp gradually. Watch the latency percentiles rather than the mean, because a mean hides the tail that users experience. Above saturation, throughput stops rising and latency climbs without bound; that knee is the useful capacity number. Pair the load test with an event loop delay histogram and a heap measurement to see which resource saturates first, because that is what to fix.

### Debugging, tracing and health

Debugging is remote inspection of a running process. Node accepts --inspect to open a debug port and --inspect-brk to stop at the first line, and a client such as Chrome DevTools or the editor's debugger attaches over the protocol. Attaching rather than adding log lines is faster for a control-flow question and, crucially, lets you inspect the live heap and the call stack at a breakpoint. In containers the debug port must be bound to a reachable address, and exposing it in production is a security risk because the protocol can execute code; keep it off by default and enable it deliberately for a session.

Source maps are what make a stack trace readable. Build with source maps enabled, ship them to the error tracker or keep them accessible to the server, and configure the runtime to use them. Node's --enable-source-maps makes stack traces resolve through the maps automatically, and the browsers do it natively. Without them a production stack trace points into minified code with names like t and e, and the cost of that in debugging time is much larger than the size of the maps.

Distributed tracing links a request across services. A trace has a global trace id and a parent span per operation, with timing, attributes and status; the trace id propagates in a header such as traceparent following the W3C Trace Context format. Instrumentation can be automatic for HTTP and database clients, or manual around a function that matters. Sampling is essential at volume: keep all errors, keep a small percentage of successes, and prefer tail-based sampling, which decides after the trace completes and therefore can keep the interesting ones. Correlating the trace id with the log line is what turns two tools into one investigation.

Health endpoints come in three kinds and conflating them causes outages. Liveness answers whether the process should be restarted and should be cheap and almost always true. Readiness answers whether traffic should be routed to it, and must check that dependencies are reachable and that configuration has loaded. A startup probe covers a slow first boot. Making liveness depend on a database turns a brief database blip into a fleet-wide restart storm, which is one of the most reliably self-inflicted outages in modern operations. Keep liveness shallow and let readiness carry the dependency checks.

Growth is a shape, not a stopwatch. Count the operations for several sizes and watch how the count scales:

```js
function opsFor(n) {
  let ops = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) ops++;
  }
  return ops;   // n(n+1)/2 — O(n^2)
}
for (const n of [10, 20, 40]) console.log(n, opsFor(n), opsFor(n) / (n * n));
```

Once you have a closed form you can predict a size you would never run, which is the point of the analysis:

```js
const quadratic = (n) => (n * (n + 1)) / 2;
const linear = (n) => n;
const logarithmic = (n) => Math.ceil(Math.log2(n + 1));
for (const n of [1e3, 1e4, 1e5]) {
  console.log(n, { quadratic: quadratic(n), linear: linear(n), log: logarithmic(n) });
}
```

Amortised cost is the honest label for an occasional resize: one call is expensive, but spread across the calls that filled the array it is constant:

```js
function amortisedPush(n) {
  let size = 1, copies = 0, pushes = 0;
  const push = () => {
    pushes++;
    if (pushes > size) { copies += size; size *= 2; }
  };
  for (let i = 0; i < n; i++) push();
  return copies / n;   // approaches 1 — O(1) amortised
}
console.log(amortisedPush(1_000_000));
```

When you do time real code, warm it up, run the body enough times to be measurable, and take the median rather than a single reading:

```js
function bench(label, fn, iters = 1_000_000) {
  fn(); // warm up the JIT
  const times = [];
  for (let r = 0; r < 5; r++) {
    const t0 = performance.now();
    for (let i = 0; i < iters; i++) fn();
    times.push((performance.now() - t0) / iters);
  }
  times.sort((a, b) => a - b);
  console.log(label, (times[2] * 1e6).toFixed(1), 'ns/op');
}
bench('increment', () => { let x = 0; x++; });
```

A benchmark only means something alongside a correctness check, so prove the fast path and the simple path agree before you trust the numbers:

```js
const fast = (xs) => xs.reduce((a, b) => a + b, 0);
const simple = (xs) => { let s = 0; for (const x of xs) s += x; return s; };
const data = Array.from({ length: 1000 }, (_, i) => i);
console.log(fast(data), simple(data), fast(data) === simple(data));
```

### Measuring real performance

Wall-clock timing of a whole function is a poor instrument because it mixes setup, garbage collection and the rest of the machine. performance.now returns a high-resolution timestamp suitable for durations, and the difference of two reads is the standard measurement. Repeat the work many times and report a percentile rather than a single sample, because the first run is dominated by JIT compilation and warm-up and the maximum is usually an unrelated interrupt. Discard a warm-up phase, take several hundred iterations, and report the median or the ninth decile.

Microbenchmarks mislead more often than they inform. The JIT compiler optimises based on the observed types in a way that differs from production, dead code can be eliminated so a benchmark measures nothing, and an inlined loop in a hot function behaves differently from the same loop spread across modules. When a microbenchmark says a construct is faster, treat the result as a hypothesis to confirm with a profile of the real application rather than a conclusion. If the difference is under a few tens of percent, it will be swamped by everything else.

Profiling answers the question a benchmark cannot: where did the time actually go. A sampling profiler records the call stack at a fixed interval and aggregates the samples into a tree, so the leaf frames with the most self time are the ones doing the work. A flame graph renders that tree with width proportional to time and depth proportional to stack depth; a wide frame near the top means many calls, a wide frame near the bottom means an expensive leaf. Read the graph from the widest frames inward, not from the code you happen to suspect.

Counters are the other half of the picture. Number of allocations, garbage collections per second, bytes allocated per request and event loop delay together explain a performance problem that a profile shows but does not diagnose. A function that is hot and allocates heavily is a candidate for reuse; a function that is hot and does not allocate is a candidate for an algorithmic change. Node's perf_hooks module exposes both the histogram for delay and the performance observer for measuring named marks and measures.

Beware the measurement changing the thing measured. A console.log in a hot path dominates the cost of the path. Adding a counter to a loop that runs millions of times per second can double its time. Measuring the memory of a large object by serialising it is itself an allocation. Guard the instrumentation behind a flag, keep the counters numeric and cheap, and prefer sampling to instrumenting when the code path is very hot. If the measurement is only enabled in development, it can be richer.

Finally, decide the acceptance threshold before you optimise. A page that renders in two hundred milliseconds is not improved in any way a user can perceive by making it one hundred and eighty. Optimise against a stated budget and a stated percentile, for example a ninety-fifth percentile response under two hundred milliseconds, and stop when the budget is met. Without a budget, optimisation becomes an unbounded activity that trades clarity for a difference nobody can feel and that the next dependency update can erase.

### Choosing the right structure

The choice of data structure usually dominates the choice of algorithm. Membership testing is the clearest case: Array.prototype.includes is a linear scan, so a filter over a list that checks membership in another array is quadratic, while a Set turns the same work linear. The same transformation applies to counting with an object or Map instead of filtering for each key, to grouping with a Map instead of repeated finds, and to looking up a record by id in a Map instead of in an array. These four rewrites remove the majority of accidental quadratic behaviour in application code.

Arrays win when order matters, when you need random access by position, when the data is small, or when you iterate the whole collection far more often than you look things up. Elements are stored contiguously, iteration is fast and predictable, and the engine optimises array access heavily. Insertion and removal in the middle are linear because the tail has to move, so a queue built on Array.prototype.shift is quadratic over the whole sequence even though each call looks cheap. Use a dedicated deque or an index-pointer technique for that pattern.

Maps and Sets are the general-purpose lookup structures. Map preserves insertion order, allows any key including objects and NaN, and exposes size directly. Plain objects are faster to create and are the right representation for records with a known shape and string keys, but they require Object.keys to count, coerce keys to strings, and inherit prototype properties unless created with Object.create(null) or a null-prototype literal. Use a Map whenever the key is not a string, whenever the insertion order is meaningful, or whenever the collection is genuinely a collection rather than a record.

Typed arrays are the right tool for numeric data at scale. A Float64Array of a million values uses eight megabytes of contiguous memory and has no per-element boxing, while a plain array of the same numbers is substantially larger and slower to sum. Typed arrays have a fixed length, so they cannot grow, and they do not sort with the comparison semantics of a normal array. For graphics, signal processing, binary protocols and numeric kernels, they are the correct choice; for ordinary business data they are unnecessary complexity.

An array is a stack for free; a queue is not, because `shift` moves every element that follows:

```js
const stack = [];
stack.push(1); stack.push(2);
console.log(stack.pop(), stack.length);   // 2 1

const queue = [];
queue.push(1); queue.push(2);
console.log(queue.shift());               // 1 — O(n)
```

A ring buffer gives O(1) enqueue and dequeue with a fixed capacity:

```js
class RingBuffer {
  #buf; #head = 0; #size = 0;
  constructor(capacity) { this.#buf = new Array(capacity); }
  push(value) {
    if (this.#size === this.#buf.length) throw new Error('full');
    this.#buf[(this.#head + this.#size) % this.#buf.length] = value;
    this.#size++;
  }
  shift() {
    if (!this.#size) return undefined;
    const value = this.#buf[this.#head];
    this.#buf[this.#head] = undefined;
    this.#head = (this.#head + 1) % this.#buf.length;
    this.#size--;
    return value;
  }
  get length() { return this.#size; }
}
const q = new RingBuffer(3);
q.push('a'); q.push('b'); q.push('c');
console.log(q.shift(), q.shift(), q.length);   // a b 1
```

A linked list is worth writing once so the pointer juggling is concrete:

```js
class LinkedList {
  #head = null; #tail = null; #size = 0;
  push(value) {
    const node = { value, next: null };
    if (this.#tail) this.#tail.next = node; else this.#head = node;
    this.#tail = node; this.#size++;
    return this;
  }
  get head() { return this.#head; }
  get size() { return this.#size; }
  *[Symbol.iterator]() {
    for (let node = this.#head; node; node = node.next) yield node.value;
  }
}
const list = new LinkedList();
list.push(1).push(2).push(3);
console.log([...list], list.size);   // [ 1, 2, 3 ] 3
```

Reversing in place and detecting a cycle with fast and slow pointers are the two canonical list exercises:

```js
function reverse(head) {
  let prev = null;
  for (let node = head; node; ) {
    const next = node.next; node.next = prev; prev = node; node = next;
  }
  return prev;
}
const nodes = [1, 2, 3].map((value) => ({ value, next: null }));
nodes.forEach((node, i) => { node.next = nodes[i + 1] ?? null; });
console.log(reverse(nodes[0]).value);   // 3

function hasCycle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next; fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}
console.log(hasCycle({ value: 1, next: { value: 2, next: null } }));   // false
```

A monotonic stack answers questions about the next greater element in a single pass:

```js
function nextGreater(values) {
  const out = new Array(values.length).fill(-1);
  const stack = [];   // indices, values decreasing
  for (let i = 0; i < values.length; i++) {
    while (stack.length && values[stack.at(-1)] < values[i]) out[stack.pop()] = values[i];
    stack.push(i);
  }
  return out;
}
console.log(nextGreater([2, 1, 3, 4, 0]));   // [ 3, 3, 4, -1, -1 ]
```

### Queues and deques

A queue is first in, first out, and a plain array is a poor queue. push and shift together are quadratic over the whole sequence because shift moves every remaining element down one index. For a handful of items it is fine; for a queue of a hundred thousand tasks it is the dominant cost. The two standard fixes are a deque backed by an object with head and tail indices, and a fixed-size ring buffer. Both give constant-time enqueue and dequeue and both are about twenty lines of code.

An index-pointer queue keeps the backing array and an integer head. Enqueue is push and dequeue is a read at head followed by an increment. The array still grows and never shrinks, so it is appropriate for a bounded burst and not for a queue that runs forever. Adding a compaction step that copies the live suffix back to the front when head exceeds some threshold keeps memory proportional to the live size, at the cost of an occasional linear copy that is still amortised constant.

A ring buffer preallocates a fixed capacity, keeps head, tail and size, and wraps the indices modulo the capacity. It is the right structure for a bounded queue, a sliding window of recent events, or a log buffer, and it makes the memory bound explicit and testable. Enqueue on a full ring either drops the oldest element or rejects, and that decision is a policy the caller should make rather than a detail hidden in the implementation. A ring buffer is also the fastest way to keep the last n measurements for a percentile calculation.

A deque supports push and pop at both ends in constant time, which makes it both a queue and a stack. The classic use is the sliding-window maximum: maintain a deque of indices whose values are decreasing, pop from the back while the new value is larger, pop from the front while the front is outside the window, and the front is the maximum. This is linear where the naive version is quadratic, and it generalises to any windowed aggregate whose combining operation is associative and idempotent enough to allow removal.

Priority queues are a different structure, covered with heaps, and the temptation to fake one by sorting is worth naming. Sorting the whole collection on every insert is linearithmic per insert; inserting into a sorted array with binary search plus a splice is linear per insert because of the shift; a binary heap is logarithmic per insert and constant to peek. Task schedulers, rate limiters that must consider deadlines, and any algorithm described as taking the cheapest first should use a heap rather than an array that is re-sorted.

Whatever structure you choose, name the operations after the domain. A queue of retry attempts reads better with enqueue and dequeue than with push and shift, and the wrapper is the place to add the bound, the metric and the policy for a full buffer. The structure itself is a dozen lines; the value is in the intent and the invariants it makes checkable, and in the fact that swapping the implementation later does not require touching the callers.

### Linked structures

A singly linked list stores a value and a reference to the next node, with the head kept by the caller. It gives constant-time insertion and removal at a known node, which arrays cannot, and it wastes memory on the pointer and loses locality of reference, which arrays do not. In a language with a garbage collector and no pointer arithmetic, the honest uses are a queue with an explicit tail pointer, an LRU cache with a doubly linked list plus a hash map, and a free list that reuses nodes.

Traversal is the same loop in every operation: keep a previous pointer, a current pointer and sometimes a next pointer, and update them in the right order. Reversing a list is the canonical exercise and it is worth knowing by heart, because the same three-pointer dance appears in removal and in-place partitioning. The detail that breaks implementations is saving the next reference before overwriting the current node's next pointer, since overwriting first loses the rest of the list and produces a single-element list that looks correct until you print it.

A doubly linked list adds a previous pointer so removal is constant-time given the node, and so iteration can go backwards. The LRU cache is its showcase application: a hash map from key to node gives constant lookup, the list orders nodes by recency, a hit moves the node to the front, and an insert that exceeds the capacity evicts the tail. Every operation is constant time, which is exactly what the doubly linked list buys over an array where moving a node to the front would be linear.

Sentinel nodes remove the special cases that make list code fragile. A permanent head node and a permanent tail node mean every insertion and removal happens between two real nodes, so there is no branch for the empty list and none for the first or last element. The code becomes uniform and the bugs disappear. The cost is one extra node and a slightly denser mental model, and it is a trade worth making whenever the list is a core data structure rather than a curiosity.

A map is only as good as its keys: object keys stringify, so two distinct objects collide, and a mutating key disappears:

```js
const m = new Map();
const key = { id: 1 };
m.set(key, 'a');
m.set({ id: 1 }, 'b');
console.log(m.size, m.get(key));   // 2 'a'

const bad = {};
bad[1] = 'num'; bad['1'] = 'str';
console.log(Object.keys(bad).length, bad[1]);   // 1 'str'
```

A tiny hash table shows why collisions need buckets rather than overwrites:

```js
class HashMap {
  #buckets; #n = 0;
  constructor(size = 16) { this.#buckets = Array.from({ length: size }, () => []); }
  #index(key) {
    const s = String(key);
    let h = 2166136261;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
    return (h >>> 0) % this.#buckets.length;
  }
  set(key, value) {
    const bucket = this.#buckets[this.#index(key)];
    const found = bucket.find((entry) => entry[0] === key);
    if (found) { found[1] = value; return; }
    bucket.push([key, value]); this.#n++;
    if (this.#n > this.#buckets.length * 0.75) this.#grow();
  }
  get(key) { return this.#buckets[this.#index(key)].find((entry) => entry[0] === key)?.[1]; }
  #grow() {
    const old = this.#buckets;
    this.#buckets = Array.from({ length: old.length * 2 }, () => []);
    const entries = old.flat(); this.#n = 0;
    for (const [k, v] of entries) this.set(k, v);
  }
}
const hm = new HashMap(4);
for (let i = 0; i < 10; i++) hm.set('k' + i, i * i);
console.log(hm.get('k7'), hm.get('missing'));   // 49 undefined
```

A set answers membership and deduplicates in one structure, and an LRU cache combines a Map's insertion order with a size cap:

```js
class LRU {
  #map = new Map(); #max;
  constructor(max) { this.#max = max; }
  get(key) {
    if (!this.#map.has(key)) return undefined;
    const value = this.#map.get(key);
    this.#map.delete(key); this.#map.set(key, value);   // refresh recency
    return value;
  }
  set(key, value) {
    this.#map.delete(key);
    this.#map.set(key, value);
    if (this.#map.size > this.#max) this.#map.delete(this.#map.keys().next().value);
  }
}
const lru = new LRU(2);
lru.set('a', 1); lru.set('b', 2); lru.get('a'); lru.set('c', 3);
console.log(lru.get('b'), lru.get('a'));   // undefined 1
```

Counting and grouping with a Map keeps insertion order and never coerces the key:

```js
const words = ['a', 'b', 'a', 'c', 'b', 'a'];
const counts = new Map();
for (const word of words) counts.set(word, (counts.get(word) ?? 0) + 1);
console.log([...counts]);   // [ [ 'a', 3 ], [ 'b', 2 ], [ 'c', 1 ] ]

const byWord = new Map();
for (const word of words) byWord.set(word, [...(byWord.get(word) ?? []), word.length]);
console.log(byWord.get('a'));   // [ 1, 1, 1 ]
